const cfg = $('Config').first().json;
const kev = $('New KEV (24h)').all().map(i => i.json).filter(r => r && r.cve_id);
const watch = $('New CVE Watch (24h)').all().map(i => i.json).filter(r => r && r.cve_id);
const arts = $('Relevant articles (24h)').all().map(i => i.json).filter(a => a && a.link);
const today = new Date().toLocaleDateString('en-AU', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'Australia/Adelaide' });
const pct = (x) => x == null ? 'n/a' : (x * 100).toFixed(0) + '%';
const sev = (r) => r.cvss_score != null ? `${r.cvss_severity || ''} ${r.cvss_score}`.trim() : 'CVSS n/a';
const one = (t, n = 220) => String(t || '').replace(/\s+/g, ' ').trim().slice(0, n);
const L = [];
L.push(`Threat intel daily note – ${today} (last 24 h)`);
L.push(`Sources: CISA KEV, NVD, FIRST EPSS, vendor PSIRTs, ACSC/CISA advisories, security news. Filtered to products in our client environments.`);
L.push('');
L.push(`1. NEW CONFIRMED-EXPLOITED VULNERABILITIES (CISA KEV) – ${kev.length}`);
if (!kev.length) L.push('   None added in the last 24 h.');
for (const r of kev) {
  L.push(`   - ${r.cve_id} | ${r.product_group || r.vendor} – ${r.vendor} ${r.product} | ${sev(r)} | EPSS ${pct(r.epss_score)} | ransomware use: ${r.ransomware || 'Unknown'} | US federal due ${r.due_date}`);
  if (r.ai_summary) L.push(`     ${one(r.ai_summary, 300)}`);
  L.push(`     Action: ${one(r.ai_reason || r.remediation || r.required_action || 'Apply vendor patch', 240)}`);
  if (r.remediation && r.ai_reason) L.push(`     Fix: ${one(r.remediation, 200)}${r.advisory_url ? ' – ' + r.advisory_url : ''}`);
}
L.push('');
// collapse browser batches
const groups = {}; const single = [];
for (const r of watch) { if (r.batch_key) (groups[r.batch_key] ||= []).push(r); else single.push(r); }
const batches = Object.entries(groups).map(([k, list]) => { const top = list.reduce((a, b) => (b.cvss_score > a.cvss_score ? b : a)); const [prod, ver] = k.split('@'); const name = prod.replace(/-/g, ' '); return { ...top, cve_id: `${list.length} CVEs`, _label: `${name} release ${ver}`, ai_summary: null, ai_reason: `Update ${name} to ${ver} on all managed endpoints (${list.length} CVEs, highest ${top.cvss_severity} ${top.cvss_score}).` }; });
const entries = [...single, ...batches].sort((a, b) => (b.cvss_score || 0) - (a.cvss_score || 0));
L.push(`2. NEW HIGH-SEVERITY CVEs IN OUR STACK (NVD, CVSS >= ${cfg.CVSS_MIN}, not yet in KEV) – ${entries.length}`);
if (!entries.length) L.push('   None published in the last 24 h.');
for (const r of entries.slice(0, 15)) {
  L.push(`   - ${r._label ? r._label + ' (' + r.cve_id + ')' : r.cve_id} | ${r.product_name || r.product_group || r.matched_vendor}${r.product_group && r.product_name && r.product_group !== r.product_name ? ' (' + r.product_group + ')' : ''} | ${sev(r)} | EPSS ${pct(r.epss_score)}`);
  if (r.ai_summary) L.push(`     ${one(r.ai_summary, 300)}`); else if (!r._label) L.push(`     ${one(r.description, 220)}`);
  if (r.ai_reason) L.push(`     Action: ${one(r.ai_reason, 240)}`);
  if (r.remediation) L.push(`     Fix: ${one(r.remediation, 200)}${r.advisory_url ? ' – ' + r.advisory_url : ''}`);
}
if (entries.length > 15) L.push(`   ... ${entries.length - 15} more on the dashboard`);
L.push('');
L.push(`3. RELEVANT NEWS AND ADVISORIES – ${arts.length}`);
if (!arts.length) L.push('   Nothing relevant in the last 24 h.');
for (const a of arts.slice(0, 12)) {
  L.push(`   - [${a.product_group || 'General'}] ${one(a.title, 140)} (${a.source})`);
  if (a.ai_summary) L.push(`     ${one(a.ai_summary, 300)}`); else L.push(`     ${one(a.summary, 200)}`);
  if (a.ai_reason) L.push(`     Why it matters: ${one(a.ai_reason, 220)}`);
  L.push(`     ${a.link}`);
}
L.push('');
L.push(`Dashboard: ${cfg.DASHBOARD_URL}`);
L.push(`Generated automatically by the threat-intel pipeline. Summaries are AI-assisted; verify before acting on a client ticket.`);
const note = L.join('\n');
const note_date = new Date().toLocaleDateString('en-CA', { timeZone: 'Australia/Adelaide' });
return [{ json: { note, note_date, counts: { kev: kev.length, watch: entries.length, articles: arts.length }, subject: `[Threat Intel] Daily ticket note – ${today} · KEV ${kev.length} · CVEs ${entries.length} · news ${arts.length}` } }];
